  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(
      in oklab,
      var(--roc-sh-color-muted) 50%,
      transparent
    );
  }
}
.roc-u-p-2 {
  padding: calc(var(--roc-sh-spacing) * 2);
}
.roc-u-px-2 {
  padding-inline: calc(var(--roc-sh-spacing) * 2);
}
.roc-u-text-left {
  text-align: left;
}
.roc-u-align-middle {
  vertical-align: middle;
}
.roc-u-text-sm {
  font-size: var(--roc-sh-text-sm);
  line-height: var(--roc-sh-tw-leading, var(--roc-sh-text-sm--line-height));
}
.roc-u-font-medium {
  --roc-sh-tw-font-weight: var(--roc-sh-font-weight-medium);
  font-weight: var(--roc-sh-font-weight-medium);
}
.roc-u-whitespace-nowrap {
  white-space: nowrap;
}
.roc-u-text-foreground {
  color: var(--roc-sh-color-foreground);
}
.roc-u-text-muted-foreground {
  color: var(--roc-sh-color-muted-foreground);
}
.roc-u-transition-colors {
  transition-property:
    color, background-color, border-color, outline-color, text-decoration-color,
    fill, stroke, --roc-sh-tw-gradient-from, --roc-sh-tw-gradient-via,
    --roc-sh-tw-gradient-to;
  transition-timing-function: var(
    --roc-sh-tw-ease,
    var(--roc-sh-default-transition-timing-function)
  );
  transition-duration: var(
    --roc-sh-tw-duration,
    var(--roc-sh-default-transition-duration)
  );
}
@media (hover: hover) {
  .roc-u-hover\:bg-muted\/50:hover {
    background-color: color-mix(in srgb, #f5f5f5 50%, transparent);
  }
  @supports (color: color-mix(in lab, red, red)) {
    .roc-u-hover\:bg-muted\/50:hover {
      background-color: color-mix(
        in oklab,
        var(--roc-sh-color-muted) 50%,
        transparent
      );
    }
  }
}
.roc-u-has-aria-expanded\:bg-muted\/50:has([aria-expanded="true"]) {
  background-color: color-mix(in srgb, #f5f5f5 50%, transparent);
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(
      in oklab,
      var(--roc-sh-color-muted) 50%,
      transparent
    );
  }
}
.roc-u-data-\[state\=selected\]\:bg-muted[data-state="selected"] {
  background-color: var(--roc-sh-color-muted);
}
.roc-u-\[\&_tr\]\:border-b tr {
  border-bottom-style: var(--roc-sh-tw-border-style);
  border-bottom-width: 1px;
}
.roc-u-\[\&_tr\:last-child\]\:border-0 tr:last-child {
  border-style: var(--roc-sh-tw-border-style);
  border-width: 0px;
}
.roc-u-\[\&\:has\(\[role\=checkbox\]\)\]\:pr-0:has([role="checkbox"]) {
  padding-right: 0px;
}
.roc-u-\[\&\>\[role\=checkbox\]\]\:translate-y-\[2px\] > [role="checkbox"] {
  --roc-sh-tw-translate-y: 2px;
  translate: var(--roc-sh-tw-translate-x) var(--roc-sh-tw-translate-y);
}
.roc-u-\[\&\>tr\]\:last\:border-b-0 > tr:last-child {
  border-bottom-style: var(--roc-sh-tw-border-style);
  border-bottom-width: 0px;
